//! Node-API handles only transport. All authentication, authorization and
//! storage run through the same Axum router used by the standalone Rust API.
//! FFI is generated by napi-rs; no hand-written unsafe operations live here.
use axum::{
    Router,
    body::{Body, to_bytes},
    http::Request,
};
use mortise_accounts::{
    protocol::AuthConfig,
    server::{Service, router},
    store::Store,
};
use napi::{Error, Result, bindgen_prelude::Buffer};
use napi_derive::napi;
use std::collections::HashMap;
use tower::ServiceExt;

static ROUTER: tokio::sync::OnceCell<Router> = tokio::sync::OnceCell::const_new();

async fn service() -> Result<&'static Router> {
    ROUTER
        .get_or_try_init(|| async {
            let url = std::env::var("DATABASE_URL")
                .map_err(|_| Error::from_reason("Database configuration missing"))?;
            let auth = AuthConfig {
                issuer: std::env::var("MORTISE_OIDC_ISSUER")
                    .or_else(|_| std::env::var("NEON_AUTH_BASE_URL"))
                    .map_err(|_| Error::from_reason("Auth configuration missing"))?,
                client_id: std::env::var("MORTISE_OIDC_CLIENT_ID")
                    .map_err(|_| Error::from_reason("Public client configuration missing"))?,
                callback_port: std::env::var("MORTISE_OIDC_CALLBACK_PORT")
                    .ok()
                    .map(|p| p.parse())
                    .transpose()
                    .map_err(|_| Error::from_reason("Invalid callback port"))?,
                resource: std::env::var("MORTISE_OIDC_RESOURCE").ok(),
            };
            let store = tokio::task::spawn_blocking(move || Store::postgres(&url))
                .await
                .map_err(|_| Error::from_reason("Account initialization failed"))?
                .map_err(|_| Error::from_reason("Account storage unavailable"))?;
            Ok(router(Service { store, auth }))
        })
        .await
}

#[napi(object)]
pub struct HttpResponse {
    pub status: u32,
    pub headers: HashMap<String, String>,
    pub body: Buffer,
}

#[napi]
pub async fn handle_request(
    method: String,
    path: String,
    headers: HashMap<String, String>,
    body: Buffer,
) -> Result<HttpResponse> {
    if body.len() > 32 * 1024 || !path.starts_with('/') || path.starts_with("//") {
        return Err(Error::from_reason("Invalid account request"));
    }
    let mut builder = Request::builder().method(method.as_str()).uri(&path);
    for (name, value) in headers {
        if matches!(
            name.as_str(),
            "authorization" | "x-mortise-proof" | "content-type"
        ) {
            builder = builder.header(name, value);
        }
    }
    let request = builder
        .body(Body::from(body.to_vec()))
        .map_err(|_| Error::from_reason("Invalid account request"))?;
    let response = service()
        .await?
        .clone()
        .oneshot(request)
        .await
        .map_err(|_| Error::from_reason("Account request failed"))?;
    let status = response.status().as_u16() as u32;
    let headers = response
        .headers()
        .iter()
        .filter_map(|(name, value)| {
            value
                .to_str()
                .ok()
                .map(|v| (name.to_string(), v.to_string()))
        })
        .collect();
    let body = to_bytes(response.into_body(), 1024 * 1024)
        .await
        .map_err(|_| Error::from_reason("Account response too large"))?;
    Ok(HttpResponse {
        status,
        headers,
        body: body.to_vec().into(),
    })
}
